userscript.function:

    window.isBridgeWindow = true;
    window.progressOn = progressOn;
    window.progressOff = progressOff;

<% if("HIDE_PARAMS".equals(step)){ %>
    var f = document.createElement('form');
    f.id = 'pf';
    f.target = '_self';
    f.style.display = 'none';

    var addHidden = function(form, name, value) {
        var input = document.createElement('input');
        input.type = 'hidden';
        input.name = name;
        input.value = value;
        form.insertBefore(input, null);
    }
    document.body.appendChild(f)
    addHidden(f, "isHidden", "true");
    var hideTarget = <%= soResult %>;
    if(Sepoa.request){
        var extParams = $.extend(true, {}, Sepoa.request);
        delete extParams.ln;
        delete extParams.ssoKey;
        delete extParams.url;
        hideTarget.params = $.extend(true, extParams, hideTarget.params || {});
    } 
    if(hideTarget.params){
        for (var i in hideTarget.params) {
            addHidden(f, i, hideTarget.params[i]);
        }
    }
    if(hideTarget.token){
        addHidden(f, 's-token', hideTarget.token);
    }
    if(window.CONTEXT_NAME && hideTarget.url.indexOf(window.CONTEXT_NAME) != 0){
    	hideTarget.url = (window.CONTEXT_NAME || '') + hideTarget.url;
    }
    addHidden(f, 'url', hideTarget.url);
    f.action = (window.CONTEXT_NAME || '') + '/link.sux';
    f.method = 'post';
    f.submit();
    return;
<% }else if("DRAW_PAGE".equals(step)){ %>
    var frame = $(layoutObj.cells('a').cell).find('.dhx_cell_cont_layout')[0].appendChild($('<iframe class="sepoa-link-frame" name="sepoa-link-frame" style="width:100%;height:100%;border:0px;padding:0px;margin:0px;"></iframe>')[0])

    var pid = "LINK_" + new Date().getTime();

    if(!SUX.root.modalPopupInfo){
        SUX.root.modalPopupInfo = {};
    }
    SUX.root.modalPopupInfo[pid] = {
        params: Sepoa.request
    };
    (function() {
        var addHidden = function(form, name, value) {
            var input = document.createElement('input');
            input.type = 'hidden';
            input.name = name;
            input.value = value;
            form.insertBefore(input, null);
        }
        var form = document.body.appendChild($('<form target="sepoa-link-frame" style="display:none"></form>')[0]);
        addHidden(form, "parameterId", pid);
        addHidden(form, "isPopup", true);
        addHidden(form, "onLink", true);
        addHidden(form, "isRealPopup", true);
        for (var idx in Sepoa.request) {
            addHidden(form, idx, Sepoa.request[idx]);
        }

        form.action = Sepoa.request.url;
        form.method = "post";
        form.submit();
    }())
<% }else if("ALERT".equals(step)){ %>
    Alert(sUtils.cache.text.get("BASE_LINK.STATUS_<%=soResult%>"));
<% } %>
